//! Detached DataList copies preserve real independent nodes and collections.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><datalist id=datalist title=seed>Fallback<span id=span>Text</span><!--marker--></datalist><datalist id=choices><option value=one>One</option></datalist><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://datalist-copy.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]fn datalist_detached_copy_native_shallow_preserves_independent_attributes_and_collection(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var x=document.getElementById('choices'),original=x.options; x.setAttribute('title','A\udfffZ');var old=x.getAttributeNode('title'),copy=x.cloneNode(false),attr=copy.getAttributeNode('title'),list=copy.options;
if(copy===x||!(copy instanceof HTMLDataListElement)||copy.ownerDocument!==document||copy.parentNode!==null||copy.firstChild!==null||attr===old||attr.ownerElement!==copy||attr.ownerDocument!==document||attr.value!=='A\udfffZ'||list===original||list!==copy.options||list.length!==0||original.length!==1)throw 'independent shallow DataList copy';copy.setAttribute('title','copy');if(old.value!=='A\udfffZ'||attr.value!=='copy')throw 'independent copied attributes';
"#);}
#[test]fn datalist_detached_copy_native_deep_preserves_real_ordinary_descendants(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var x=document.getElementById('datalist'),copy=x.cloneNode(true);if(!(copy instanceof HTMLDataListElement)||copy.parentNode!==null||copy.childNodes.length!==3||copy.firstChild.data!=='Fallback'||copy.lastChild.data!=='marker'||copy.childNodes[1]===x.childNodes[1]||copy.childNodes[1].parentNode!==copy||copy.childNodes[1].ownerDocument!==document||copy.options.length!==0||copy.options===x.options)throw 'real copied DataList topology';copy.childNodes[1].textContent='copy';if(x.childNodes[1].textContent!=='Text')throw 'independent deep children';
"#);}
#[test]fn datalist_detached_copy_inert_import_preserves_exact_attributes_and_option_refusals(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','datalist'),a=owner.createElementNS('http://www.w3.org/1999/xhtml','span');source.setAttribute('title','R\ud800Z');a.setAttribute('id','actual');a.appendChild(owner.createTextNode('One'));source.appendChild(a);var original=source.options,copy=document.importNode(source,true),list=copy.options,b=copy.firstChild;if(!(copy instanceof HTMLDataListElement)||copy.ownerDocument!==document||copy.parentNode!==null||copy===source||copy.getAttribute('title')!=='R\ud800Z'||list===original||list!==copy.options||list.length!==0||b===a||b.ownerDocument!==document||b.parentNode!==copy||b.textContent!=='One'||b.getAttributeNode('id')===a.getAttributeNode('id')||source.ownerDocument!==owner||a.ownerDocument!==owner)throw 'inert ordinary descendants imported independently';b.textContent='copy';if(a.textContent!=='One'||original.length!==0)throw 'independent imported children';var choices=owner.createElementNS('http://www.w3.org/1999/xhtml','datalist'),option=owner.createElementNS('http://www.w3.org/1999/xhtml','option');choices.appendChild(option);var options=choices.options;
"#);
for raw in [false,true]{p.begin_job();run(&mut d,&mut f,&mut p,if raw{"option.setAttribute('name','A\\ud800Z');"}else{"option.setAttribute('name','actual');"});p.state.rebuild(&d).unwrap();let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone(),p.state.dom.collections.len());let e=p.runtime.execute("document.importNode(choices,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("conventional SELECT")||e.contains("unpaired attribute"),"{e}");assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone(),p.state.dom.collections.len()),before);p.begin_job();run(&mut d,&mut f,&mut p,"var recovered=document.importNode(choices,false);if(recovered.options.length!==0||options!==choices.options||options.length!==1||options[0]!==option||option.ownerDocument!==owner||recovered.parentNode!==null||recovered.ownerDocument!==document)throw 'option import refuses atomically and shallow import recovers';");}}

#[test]
fn datalist_detached_copy_resource_refusals_publish_nothing_and_recover(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var source=new Document().createElementNS('http://www.w3.org/1999/xhtml','datalist');source.setAttribute('title','retained');"}else{"var source=document.getElementById('datalist');source.setAttribute('title','retained');"});run(&mut d,&mut f,&mut p,"var attr=source.getAttributeNode('title'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let retained=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};let code=if inert{"var copy=document.importNode(source,true);"}else{"var copy=source.cloneNode(true);"};let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound")||e.contains("time"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=retained;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.getAttribute('title')!=='retained'||source.getAttributeNode('title')!==attr||attr.ownerElement!==source||watch.takeRecords().length||document.getElementById('neighbor').value!=='seed')throw 'atomic copy refusal';");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"if(!(copy instanceof HTMLDataListElement)||copy.parentNode!==null||copy.ownerDocument!==document||copy.getAttribute('title')!=='retained'||copy.options.length!==0||copy.getAttributeNode('title')===attr||watch.takeRecords().length)throw 'fresh detached copy recovery';");assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());let(a,b,c)=p.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());}}
}



#[test]
fn datalist_detached_copy_saved_child_method_checks_origin_before_copy_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('datalist'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var method=frame.contentWindow.Node.prototype.cloneNode,copy=method.call(source,false);if(!(copy instanceof HTMLDataListElement)||copy.parentNode!==null)throw 'same origin native copy';");p.set_location(&crate::navigation::address("https://other-copy.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute("method.call(source,false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);p.set_location(&crate::navigation::address("https://datalist-copy.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"copy=method.call(source,false);if(copy.getAttribute('title')!=='seed'||copy.ownerDocument!==document||copy.parentNode!==null)throw 'fresh copy origin recovery';");}



#[test]
fn datalist_detached_copy_copies_nonce_unsafety_without_fabricating_source_mutation(){let(mut d,mut f,mut p)=fixture();let original=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("datalist")).unwrap();d.nonce_unsafe_nodes.insert(original);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes[original]);let Value::Host(copy)=p.runtime.execute("document.getElementById('datalist').cloneNode(false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("genuine copied node")};let copied=node_index(copy).unwrap();assert_ne!(copied,original);assert!(d.nonce_unsafe_nodes.contains(&copied));assert!(d.nonce_unsafe_nodes.contains(&original));assert_eq!(format!("{:?}",d.nodes[original]),before);assert!(p.state.detached_nodes.contains(&copied));assert!(!p.has_navigation_request());}



#[test]
fn datalist_detached_copy_native_option_deep_refusal_preserves_actual_source_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('choices'),list=source.options,option=list[0],attr=option.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone(),p.state.dom.collections.len());
 let e=p.runtime.execute("source.cloneNode(true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("Cloning")||e.contains("native state"),"{e}");assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone(),p.state.dom.collections.len()),before);p.begin_job();run(&mut d,&mut f,&mut p,"var copy=source.cloneNode(false);if(copy.options.length||copy.options===list||source.options!==list||list.length!==1||list[0]!==option||option.getAttributeNode('value')!==attr||attr.value!=='one'||watch.takeRecords().length)throw 'native option guard preserves original and allows shallow recovery';");
}
#[test]
fn datalist_detached_copy_active_handler_and_foreign_import_refuse_atomically(){
 let mut d=crate::html::parse("<html><body><datalist id=bad title=seed onclick='return 1;'></datalist><datalist id=clean title=seed></datalist></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var source=document.getElementById('bad');");p.state.rebuild(&d).unwrap();let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());let e=p.runtime.execute("source.cloneNode(true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("Cloning")||e.contains("handler"),"{e}");assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),before);p.begin_job();run(&mut d,&mut f,&mut p,"var copy=document.getElementById('clean').cloneNode(true);if(copy.getAttribute('title')!=='seed'||copy.parentNode!==null)throw 'handler-free recovery';var owner=new Document(),inert=owner.createElementNS('http://www.w3.org/1999/xhtml','datalist');inert.setAttributeNS('urn:foreign','foreign','kept');");let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());let e=p.runtime.execute("document.importNode(inert,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("namespaced")||e.contains("unsupported"),"{e}");assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),before);p.begin_job();run(&mut d,&mut f,&mut p,"if(inert.ownerDocument!==owner||inert.getAttributeNS('urn:foreign','foreign')!=='kept')throw 'foreign source preserved';inert.removeAttributeNS('urn:foreign','foreign');var recovered=document.importNode(inert,true);if(!(recovered instanceof HTMLDataListElement)||recovered.ownerDocument!==document||recovered.parentNode!==null||inert.ownerDocument!==owner)throw 'fresh import recovery';");assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());
}
